/* Listing fields are shared by registration, preview, cards, filters and details. */
const LISTING_OPTIONS={
 heating:[['central','Төвийн дулаан'],['individual','Бие даасан'],['district','Дүүргийн дулаан'],['electric','Цахилгаан'],['stove','Зуух']],
 cooling:[['wall','Ханын агааржуулагч'],['standing','Зөөврийн агааржуулагч'],['ceiling','Таазны агааржуулагч']],
 amenities:[['bed','Ор'],['desk','Ширээ'],['wardrobe','Хувцасны шүүгээ'],['dining','Хоолны ширээ'],['sofa','Буйдан'],['shoe','Гутлын шүүгээ'],['fridge','Хөргөгч'],['washer','Угаалгын машин'],['dryer','Хатаагч'],['shower','Шүршүүр'],['bath','Ванн'],['bidet','Биде'],['sink','Гал тогооны угаалтуур'],['dishwasher','Аяга таваг угаагч'],['gasStove','Хийн плитка'],['induction','Индукцийн плитка'],['microwave','Богино долгионы зуух'],['oven','Шарах шүүгээ'],['tv','Телевиз'],['builtIn','Суурилуулсан шүүгээ']],
 security:[['guard','Харуул'],['videoDoor','Видео домофон'],['intercom','Домофон'],['keycard','Картын нэвтрэлт'],['cctv','Хяналтын камер'],['privateGuard','Хамгаалалтын алба'],['secureEntry','Хаалттай орц'],['windowBars','Цонхны хамгаалалт']],
 other:[['smokeAlarm','Галын дохиолол'],['balcony','Тагт'],['terrace','Террас'],['yard','Хашаа / цэцэрлэг'],['parcel','Илгээмжийн шүүгээ']],
 feeIncluded:[['heating','Дулаан'],['water','Ус'],['electricity','Цахилгаан'],['internet','Интернет'],['tv','Кабелийн телевиз'],['cleaning','Цэвэрлэгээ'],['security','Хамгаалалт'],['waste','Хог тээвэр']],
 directions:[['N','Хойд'],['NE','Зүүн хойд'],['E','Зүүн'],['SE','Зүүн өмнөд'],['S','Өмнөд'],['SW','Баруун өмнөд'],['W','Баруун'],['NW','Баруун хойд']],
 structure:[['concrete','Төмөр бетон'],['brick','Тоосго'],['wood','Мод'],['mixed','Холимог'],['other','Бусад']],
 period:[['month','Сар'],['week','Долоо хоног'],['day','Өдөр']]
};
const EDITOR_STEPS=['Байршил ба мэдээлэл','Үнэ ба нөхцөл','Тоноглол, зураг, тайлбар','Шалгах'];
const EDITOR_FIELDS=[
 ['type','province','area','khoroo','address','buildingNo','unit','showUnit','name','size','totalSize','floor','totalFloors','rooms','bathrooms','year','direction','structure','moveIn','moveInDate','latitude','longitude'],
 ['deal','rentPeriod','price','priceNegotiable','deposit','feeMode','feeMnt','feeIncluded','feeNote','minimumTerm','parkingStatus','parkingFee','parkingSpaces','garage','elevator','petPolicy','furnishing','duplex','smoking'],
 ['heating','cooling','amenities','security','other','desc','description','nearbyTransit','nearbySchool','nearbyServices','videoUrl','tourUrl','contactRole','contactName','contactPhone','agencyName','contactHours']
];
const EDITOR_ARRAYS=['feeIncluded','cooling','amenities','security','other'];
const EDITOR_CHECKS=['showUnit','priceNegotiable','garage','elevator','duplex'];
const PHOTO_LIMIT=10;
let editorReady=false,editorSaveTimer=null,editorPhotoBusy=false;
function listingDraftDefaults(){return {schemaVersion:2,currency:'MNT',type:'0',province:'Улаанбаатар',area:areas[0],khoroo:'1-р хороо',address:'',buildingNo:'',unit:'',showUnit:false,name:'',size:'',totalSize:'',floor:'',totalFloors:'',rooms:'',bathrooms:'',year:'',direction:'',structure:'',moveIn:'immediate',moveInDate:'',latitude:'',longitude:'',deal:'rent',rentPeriod:'month',price:'',priceNegotiable:false,deposit:'0',feeMode:'separate',feeMnt:'',feeIncluded:[],feeNote:'',minimumTerm:'',parkingStatus:'none',parkingFee:'0',parkingSpaces:'',garage:false,elevator:false,petPolicy:'no',furnishing:'none',duplex:false,smoking:'no',heating:'',cooling:[],amenities:[],security:[],other:[],desc:'',description:'',nearbyTransit:'',nearbySchool:'',nearbyServices:'',videoUrl:'',tourUrl:'',contactRole:'owner',contactName:'',contactPhone:'',agencyName:'',contactHours:'',photos:[]}}
function prepareListingDraft(){
 if(!editorReady){if(Number.isInteger(flowState.draft?.editorStep))listingStep=flowState.draft.editorStep;listingPhotoDraft=Array.isArray(flowState.draft?.photos)?flowState.draft.photos.slice():listingPhotoDraft;editorReady=true}
 const old=flowState.draft||{};const d={...listingDraftDefaults(),...old};
 if(old.currency!=='MNT'){d.price='';d.deposit='0'}
 for(const key of EDITOR_ARRAYS)d[key]=Array.isArray(d[key])?d[key]:[];
 d.photos=listingPhotoDraft;flowState.draft=d;return d;
}
function optionText(group,value,empty='Оруулаагүй'){return LISTING_OPTIONS[group]?.find(([key])=>key===value)?.[1]||empty}
function editorSelect(name,value,choices,required=false,refresh=false){return `<select id="listing-${name}" name="${name}" ${required?'required':''} ${refresh?'data-refresh="true"':''}><option value="">Сонгоно уу</option>${choices.map(([key,label])=>`<option value="${esc(key)}" ${String(value)===String(key)?'selected':''}>${esc(label)}</option>`).join('')}</select>`}
function editorInput(name,value,type='text',attrs=''){return `<input id="listing-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}>`}
function editorField(label,name,body,required=false,hint=''){return `<div class="editor-field"><label for="listing-${name}">${label}${required?'<em aria-label="заавал">*</em>':''}</label>${body}${hint?`<p class="editor-hint">${hint}</p>`:''}</div>`}
function editorRow(label,body,required=false){return `<div class="editor-row"><div class="editor-row-label">${label}${required?'<em>*</em>':''}</div><div class="editor-row-content">${body}</div></div>`}
function editorSection(title,body,subtitle=''){return `<section class="editor-section"><div class="editor-section-heading"><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${body}</section>`}
function editorChecks(name,choices,selected,all=false){return `<div class="editor-check-group" data-group="${name}">${all?`<label class="editor-check-all"><input type="checkbox" ${choices.every(([k])=>selected.includes(k))?'checked':''} onchange="toggleListingGroup(this,'${name}')">Бүгдийг сонгох</label>`:''}<div class="editor-check-grid">${choices.map(([key,label])=>`<label><input type="checkbox" name="${name}" value="${key}" ${selected.includes(key)?'checked':''}>${label}</label>`).join('')}</div></div>`}
function editorBoolean(name,label,on){return `<label class="editor-check"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`}
function editorBasic(d){const residential=[0,1,4].includes(Number(d.type)),ub=d.province==='Улаанбаатар';return editorSection('Байршлын мэдээлэл',
 editorRow('Зарын төрөл',editorField('Үл хөдлөх хөрөнгийн төрөл','type',editorSelect('type',d.type,types.map((v,i)=>[String(i),v]),true,true),true),true)+
 editorRow('Хаяг',`<div class="editor-grid three">${editorField('Хот / Аймаг','province',editorSelect('province',d.province,MONGOLIA_PROVINCES.map(v=>[v,v]),true,true),true)}${editorField(ub?'Дүүрэг':'Сум / Дүүрэг','area',ub?editorSelect('area',d.area,Object.keys(UB_KHOROO_COUNTS).map(v=>[v,v]),true,true):editorInput('area',d.area,'text','required maxlength="70"'),true)}${editorField(ub?'Хороо':'Баг / Хороо','khoroo',ub?`<select id="listing-khoroo" name="khoroo" required>${listingKhorooOptions(d.area,d.khoroo)}</select>`:editorInput('khoroo',d.khoroo,'text','required maxlength="70"'),true)}</div>${editorField('Гудамж / Хаяг','address',editorInput('address',d.address,'text','required maxlength="180" placeholder="Гудамж, хороолол, байрны байршил"'),true)}<div class="editor-grid">${editorField('Байр / Хашааны дугаар','buildingNo',editorInput('buildingNo',d.buildingNo,'text','maxlength="40"'))}${editorField('Тоот','unit',editorInput('unit',d.unit,'text','maxlength="30"'))}</div>${editorBoolean('showUnit','Тоотыг зар дээр нийтэд харуулах',d.showUnit)}`,true)+
 editorRow('Хотхон / Нэр',editorField('Хотхон эсвэл үл хөдлөхийн нэр','name',editorInput('name',d.name,'text','required maxlength="80" placeholder="Хотхоны нэр / Зарлах үл хөдлөхийн нэр"'),true),true)+
 editorRow('Газрын зураг',listingMapPicker(d),true))+
 editorSection('Үл хөдлөхийн дэлгэрэнгүй',
 editorRow('Талбай',`<div class="editor-grid">${editorField('Ашигтай талбай, м²','size',editorInput('size',d.size,'number','required min="1" max="10000000" step="0.01"'),true)}${editorField('Нийт талбай, м²','totalSize',editorInput('totalSize',d.totalSize,'number','min="1" max="10000000" step="0.01"'))}</div>`,true)+
 editorRow('Өрөө ба давхар',`<div class="editor-grid">${editorField('Өрөөний тоо','rooms',editorSelect('rooms',d.rooms,[['1','1 өрөө'],['2','2 өрөө'],['3','3 өрөө'],['4','4 өрөө'],['5','5+ өрөө'],['shared','Хажуу өрөө']],residential),residential)}${editorField('Ариун цэврийн өрөө','bathrooms',editorInput('bathrooms',d.bathrooms,'number',`${residential?'required':''} min="0" max="30" step="1"`),residential)}${editorField('Байрлах давхар','floor',editorInput('floor',d.floor,'number',`${Number(d.type)!==3?'required':''} min="-3" max="150" step="1"`),Number(d.type)!==3)}${editorField('Барилгын нийт давхар','totalFloors',editorInput('totalFloors',d.totalFloors,'number',`${Number(d.type)!==3?'required':''} min="1" max="150" step="1"`),Number(d.type)!==3)}</div>`)+
 editorRow('Барилгын мэдээлэл',`<div class="editor-grid three">${editorField('Ашиглалтад орсон он','year',editorInput('year',d.year,'number',`min="1900" max="${new Date().getFullYear()+5}" step="1" placeholder="Мэдэж байвал"`))}${editorField('Барилгын хийц','structure',editorSelect('structure',d.structure,LISTING_OPTIONS.structure))}${editorField('Цонхны чиглэл','direction',editorSelect('direction',d.direction,LISTING_OPTIONS.directions))}</div>`)+
 editorRow('Нүүх боломжтой өдөр',editorField('Нүүх нөхцөл','moveIn',editorSelect('moveIn',d.moveIn,[['immediate','Шууд нүүх боломжтой'],['date','Огноо сонгох'],['negotiable','Тохиролцоно']],true,true),true)+(d.moveIn==='date'?editorField('Нүүх огноо','moveInDate',editorInput('moveInDate',d.moveInDate,'date','required'),true):''),true));}
function editorPricing(d){return editorSection('Үнийн мэдээлэл',
 editorRow('Гэрээний төрөл',`<div class="editor-grid">${editorField('Түрээс / Худалдаа','deal',editorSelect('deal',d.deal,[['rent','Түрээслүүлнэ'],['sale','Зарна']],true,true),true)}${d.deal==='rent'?editorField('Түрээсийн хугацааны нэгж','rentPeriod',editorSelect('rentPeriod',d.rentPeriod,LISTING_OPTIONS.period,true,true),true):''}</div>`,true)+
 editorRow('Үнэ, ₮',`${editorBoolean('priceNegotiable','Үнийг тохиролцоно',d.priceNegotiable)}<div class="editor-grid">${editorField(d.deal==='sale'?'Худалдах үнэ, ₮':listingRentLabel(d)+', ₮','price',editorInput('price',d.price,'number',`${d.priceNegotiable?'disabled':'required'} min="1" max="1000000000000" step="1"`),!d.priceNegotiable)}${d.deal==='rent'?editorField('Барьцаа, ₮','deposit',editorInput('deposit',d.deposit,'number','required min="0" max="1000000000000" step="1"'),true):''}</div>${d.deal==='rent'?editorField('Хамгийн бага түрээслэх хугацаа','minimumTerm',editorInput('minimumTerm',d.minimumTerm,'number','min="1" max="1200" step="1"'),false,optionText('period',d.rentPeriod)+' нэгжээр оруулна.'):''}`,true))+
 editorSection('СӨХ ба ашиглалтын зардал',
 editorRow('Төлбөрийн нөхцөл',editorField('СӨХ','feeMode',editorSelect('feeMode',d.feeMode,[['separate','Сар бүр тогтмол төлбөртэй'],['actual','Бодит хэрэглээгээр'],['included','Үндсэн үнэд багтсан'],['none','СӨХ төлбөргүй']],true,true),true)+(['separate','actual'].includes(d.feeMode)?editorField(d.feeMode==='actual'?'Сарын ойролцоо төлбөр, ₮':'Сарын төлбөр, ₮','feeMnt',editorInput('feeMnt',d.feeMnt,'number',`${d.feeMode==='separate'?'required':''} min="0" max="100000000" step="1"`),d.feeMode==='separate'):'')+
 editorField('Үүнд багтсан зардал','feeIncluded',editorChecks('feeIncluded',LISTING_OPTIONS.feeIncluded,d.feeIncluded))+editorField('Нэмэлт төлбөрийн тайлбар','feeNote',`<textarea id="listing-feeNote" name="feeNote" maxlength="500" placeholder="Жишээ: цахилгааны төлбөр хэрэглээгээр тусдаа">${esc(d.feeNote)}</textarea>`),true))+
 editorSection('Зогсоол ба амьдрах нөхцөл',
 editorRow('Зогсоол',`<div class="editor-grid three">${editorField('Зогсоолын боломж','parkingStatus',editorSelect('parkingStatus',d.parkingStatus,[['none','Байхгүй'],['available','Байгаа'],['negotiable','Тохиролцоно']],true,true),true)}${d.parkingStatus==='available'?editorField('Сарын төлбөр, ₮','parkingFee',editorInput('parkingFee',d.parkingFee,'number','min="0" max="100000000" step="1"'),false,'Үнэгүй бол 0')+editorField('Зогсоолын тоо','parkingSpaces',editorInput('parkingSpaces',d.parkingSpaces,'number','min="1" max="1000" step="1"')):''}</div>${editorBoolean('garage','Гаражтай',d.garage)}${editorBoolean('elevator','Цахилгаан шаттай',d.elevator)}`)+
 editorRow('Нэмэлт нөхцөл',`<div class="editor-grid">${editorField('Тэжээвэр амьтан','petPolicy',editorSelect('petPolicy',d.petPolicy,[['yes','Зөвшөөрнө'],['no','Зөвшөөрөхгүй'],['negotiable','Тохиролцоно']],true),true)}${editorField('Тавилга','furnishing',editorSelect('furnishing',d.furnishing,[['full','Бүрэн тавилгатай'],['partial','Хагас тавилгатай'],['none','Тавилгагүй']],true),true)}${editorField('Тамхи татах','smoking',editorSelect('smoking',d.smoking,[['no','Хориглоно'],['yes','Зөвшөөрнө'],['negotiable','Тохиролцоно']],true),true)}</div>${editorBoolean('duplex','Дуплекс / Дотроо давхартай',d.duplex)}`));}
function editorFacilities(d){return editorSection('Тоноглол ба байгууламж',
 editorRow('Халаалт',editorSelect('heating',d.heating,LISTING_OPTIONS.heating))+
 editorRow('Хөргөлт',editorChecks('cooling',LISTING_OPTIONS.cooling,d.cooling))+
 editorRow('Тавилга, ахуйн хэрэгсэл',editorChecks('amenities',LISTING_OPTIONS.amenities,d.amenities,true))+
 editorRow('Хамгаалалт / Аюулгүй байдал',editorChecks('security',LISTING_OPTIONS.security,d.security,true))+
 editorRow('Бусад байгууламж',editorChecks('other',LISTING_OPTIONS.other,d.other)))+
 editorSection('Фото зураг',`<div class="editor-photo-area"><label class="editor-upload" for="listing-photos">${icon('image')}<b>Фото зураг нэмэх</b><span>JPEG / PNG · 10 хүртэл зураг · Нэг зураг 8 MB хүртэл</span><input id="listing-photos" type="file" accept="image/png,image/jpeg" multiple onchange="readListingPhotos(this)"></label><p class="editor-hint">Бодит байрны зураг оруулна уу. Эхний зураг нүүр зураг болно. Зургийг хадгалахад зориулан хэмжээг нь багасгана.</p><div id="listing-photo-preview" class="editor-photo-grid">${editorPhotosMarkup()}</div><p id="listing-photo-status" role="status"></p></div>`, 'Нүүр зураг болон дарааллыг доорх товчоор өөрчилнө үү.')+
 editorSection('Зарын гарчиг ба тайлбар',
 editorRow('Гарчиг',editorField('Жагсаалтад харагдах гарчиг','desc',editorInput('desc',d.desc,'text','required maxlength="80" placeholder="Жишээ: Нарлаг, 2 өрөө, тавилгатай байр" data-counter="80"'),true)+`<p class="editor-counter" data-count-for="desc">${d.desc.length} / 80</p>`,true)+
 editorRow('Дэлгэрэнгүй тайлбар',editorField('Байрны дэлгэрэнгүй тайлбар','description',`<textarea id="listing-description" name="description" required maxlength="2000" data-counter="2000" placeholder="Төлөвлөлт, засвар, орчин, гэрээний нөхцөл болон онцлогийг тайлбарлана уу.">${esc(d.description)}</textarea>`,true)+`<p class="editor-counter" data-count-for="description">${d.description.length} / 2000</p>`,true)+
 editorRow('Видео / 3D аялал',`<div class="editor-grid">${editorField('Видео холбоос','videoUrl',editorInput('videoUrl',d.videoUrl,'url','placeholder="https://..." maxlength="500"'))}${editorField('3D аяллын холбоос','tourUrl',editorInput('tourUrl',d.tourUrl,'url','placeholder="https://..." maxlength="500"'))}</div><p class="editor-hint">Зөвхөн https холбоос. Оруулаагүй бол аялал, видеог зар дээр зохиомлоор харуулахгүй.</p>`))+
 editorSection('Ойр орчны мэдээлэл',
 editorRow('Нийтийн тээвэр',editorField('Буудлын нэр, зай / алхах хугацаа','nearbyTransit',editorInput('nearbyTransit',d.nearbyTransit,'text','maxlength="250" placeholder="Жишээ: Төв талбайн буудал, 300 м, 5 минут"')))+
 editorRow('Сургууль / Цэцэрлэг',editorInput('nearbySchool',d.nearbySchool,'text','maxlength="250" placeholder="Нэр, зай болон тайлбар"'))+
 editorRow('Ойр орчны үйлчилгээ',editorInput('nearbyServices',d.nearbyServices,'text','maxlength="350" placeholder="Дэлгүүр, эмнэлэг, парк болон бусад"')))+
 editorSection('Зар оруулагчийн мэдээлэл',
 editorRow('Зар оруулагч',`<div class="editor-grid">${editorField('Таны оролцоо','contactRole',editorSelect('contactRole',d.contactRole,[['owner','Өмчлөгч'],['agent','Зуучлагч'],['representative','Итгэмжлэгдсэн төлөөлөгч']],true,true),true)}${editorField('Холбоо барих нэр','contactName',editorInput('contactName',d.contactName,'text','required maxlength="60"'),true)}</div>${d.contactRole==='agent'?editorField('Агентлаг / Байгууллага','agencyName',editorInput('agencyName',d.agencyName,'text','required maxlength="100"'),true):''}`,true)+
 editorRow('Холбоо барих',`<div class="editor-grid">${editorField('Утасны дугаар','contactPhone',editorInput('contactPhone',d.contactPhone,'tel','maxlength="25" placeholder="+976 9911 2233"'),false,'Оруулбал зарын холбоо барих хэсэгт харагдана.')}${editorField('Холбогдох цаг','contactHours',editorInput('contactHours',d.contactHours,'text','maxlength="80" placeholder="Жишээ: 09:00–20:00"'))}</div>`));}
function editorPhotosMarkup(){return listingPhotoDraft.map((src,i)=>`<div class="editor-photo"><img src="${src}" alt="Байрны зураг ${i+1}"><span class="editor-photo-number">${i===0?'Нүүр зураг':i+1}</span><div><button type="button" aria-label="Зураг ${i+1} нүүр болгох" onclick="moveListingPhoto(${i},0)" ${i===0?'disabled':''}>${icon('image')}</button><button type="button" aria-label="Зураг ${i+1} урагш" onclick="moveListingPhoto(${i},${i-1})" ${i===0?'disabled':''}>${icon('chevron-left')}</button><button type="button" aria-label="Зураг ${i+1} хойш" onclick="moveListingPhoto(${i},${i+1})" ${i===listingPhotoDraft.length-1?'disabled':''}>${icon('chevron-right')}</button><button type="button" aria-label="Зураг ${i+1} хасах" onclick="removeListingPhoto(${i})">${icon('close')}</button></div></div>`).join('')}
function captureListingDraft(form){
 const d=prepareListingDraft(),step=Number(form.dataset?.editorStep??listingStep),f=new FormData(form);const priorProvince=d.province,priorArea=d.area,priorAddress=listingAddressKey(d);
 for(const name of EDITOR_FIELDS[step]||[]){if(EDITOR_ARRAYS.includes(name))d[name]=f.getAll(name).filter(key=>LISTING_OPTIONS[name]?.some(([k])=>k===key));else if(EDITOR_CHECKS.includes(name))d[name]=f.has(name);else if(f.has(name))d[name]=String(f.get(name)).trim()}
 if(priorProvince!==d.province){d.area=d.province==='Улаанбаатар'?areas[0]:'';d.khoroo=d.province==='Улаанбаатар'?'1-р хороо':''}
 else if(priorArea!==d.area&&d.province==='Улаанбаатар')d.khoroo='1-р хороо';
 if(step===0&&priorAddress!==listingAddressKey(d))invalidateListingPin(d);
 if(step===1)d.currency='MNT';d.photos=listingPhotoDraft.slice();d.editorStep=listingStep;return d;
}
function persistListingDraft(){clearTimeout(editorSaveTimer);const ok=persistFlows();const status=document.getElementById('editor-save-status');if(status)status.textContent=ok?'Түр хадгаллаа · Энэ браузерт':'Хадгалах зай хүрэлцэхгүй';return ok}
function listingEditorInput(event){const input=event.target;if(input.dataset?.refresh||input.name==='priceNegotiable')return;const form=event.currentTarget||input.closest('form');captureListingDraft(form);if(['latitude','longitude'].includes(input.name))listingCoordinateInput();
 if(input.dataset?.counter){const out=form.querySelector(`[data-count-for="${input.name}"]`);if(out)out.textContent=input.value.length+' / '+input.dataset.counter}
 clearTimeout(editorSaveTimer);editorSaveTimer=setTimeout(persistListingDraft,600);
}
function listingEditorChange(event){if(event.target.dataset?.refresh||event.target.name==='priceNegotiable'){captureListingDraft(event.currentTarget);persistListingDraft();render()}}
function toggleListingGroup(input,name){const form=input.closest('form');form.querySelectorAll(`input[name="${name}"]`).forEach(box=>box.checked=input.checked);captureListingDraft(form);persistListingDraft()}
function changeListingStep(step){const form=document.querySelector('#listing-editor-form');if(form)captureListingDraft(form);if(step>listingStep){const errors=validateListingDraft(flowState.draft,listingStep);if(errors.length){showListingErrors(errors);return}}listingStep=Math.max(0,Math.min(3,step));flowState.draft.editorStep=listingStep;persistListingDraft();render();scrollTo({top:0,behavior:'smooth'})}
function saveListingDraftButton(){const form=document.querySelector('#listing-editor-form');if(form)captureListingDraft(form);if(persistListingDraft())toast('Мэдээллийг түр хадгаллаа')}
function validListingLink(value){if(!value)return true;try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password}catch{return false}}
function validateListingDraft(d,step){const errors=[],add=(field,message)=>errors.push({step,field,message});const present=v=>v!==undefined&&v!==null&&String(v).trim()!=='';const num=(key,min,max,required=false)=>{if(!present(d[key])){if(required)add(key,'Энэ талбарыг бөглөнө үү.');return}const value=Number(d[key]);if(!Number.isFinite(value)||value<min||value>max)add(key,'Зөв тоон утга оруулна уу.')};
 if(step===0){
  if(!types[Number(d.type)])add('type','Зарын төрөл сонгоно уу.');if(!MONGOLIA_PROVINCES.includes(d.province))add('province','Хот / аймаг сонгоно уу.');
  for(const key of ['area','khoroo','address','name'])if(!present(d[key]))add(key,'Энэ талбарыг бөглөнө үү.');
  if(d.province==='Улаанбаатар'&&!Object.hasOwn(UB_KHOROO_COUNTS,d.area))add('area','Дүүрэг сонгоно уу.');
  if(d.province==='Улаанбаатар'&&Object.hasOwn(UB_KHOROO_COUNTS,d.area)&&!Array.from({length:UB_KHOROO_COUNTS[d.area]},(_,i)=>(i+1)+'-р хороо').includes(d.khoroo))add('khoroo','Хороо сонгоно уу.');
  num('size',1,1e7,true);num('totalSize',1,1e7);if(present(d.totalSize)&&Number(d.totalSize)<Number(d.size))add('totalSize','Нийт талбай ашигтай талбайгаас бага байж болохгүй.');
  num('floor',-3,150,Number(d.type)!==3);num('totalFloors',1,150,Number(d.type)!==3);if(present(d.floor)&&present(d.totalFloors)&&Number(d.floor)>Number(d.totalFloors))add('floor','Байрлах давхар нийт давхраас их байж болохгүй.');
  if([0,1,4].includes(Number(d.type))&&!['1','2','3','4','5','shared'].includes(String(d.rooms)))add('rooms','Өрөөний тоо сонгоно уу.');num('bathrooms',0,30,[0,1,4].includes(Number(d.type)));num('year',1900,new Date().getFullYear()+5);
  if(!['immediate','date','negotiable'].includes(d.moveIn))add('moveIn','Нүүх нөхцөл сонгоно уу.');if(d.moveIn==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(d.moveInDate)||!Number.isFinite(Date.parse(d.moveInDate))))add('moveInDate','Нүүх огноо оруулна уу.');
  if(!listingPin(d))add('location','Газрын зураг дээр байрныхаа яг байршлыг сонгох эсвэл зөв координатыг хоёуланг оруулна уу.');
 }
 if(step===1){if(!['rent','sale'].includes(d.deal))add('deal','Гэрээний төрөл сонгоно уу.');if(d.deal==='rent'&&!LISTING_OPTIONS.period.some(([k])=>k===d.rentPeriod))add('rentPeriod','Түрээсийн хугацааны нэгж сонгоно уу.');if(!d.priceNegotiable)num('price',1,1e12,true);num('deposit',0,1e12,d.deal==='rent');num('minimumTerm',1,1200);if(!['separate','actual','included','none'].includes(d.feeMode))add('feeMode','СӨХ-ийн нөхцөл сонгоно уу.');if(['separate','actual'].includes(d.feeMode))num('feeMnt',0,1e8,d.feeMode==='separate');num('parkingFee',0,1e8);num('parkingSpaces',1,1000)}
 if(step===1){for(const [key,values] of [['parkingStatus',['available','none','negotiable']],['petPolicy',['yes','no','negotiable']],['furnishing',['full','partial','none']],['smoking',['yes','no','negotiable']]])if(!values.includes(d[key]))add(key,'Нөхцөл сонгоно уу.')}
 if(step===2){if(!['owner','agent','representative'].includes(d.contactRole))add('contactRole','Зар оруулагчийн оролцоо сонгоно уу.');for(const key of ['desc','description','contactName'])if(!present(d[key]))add(key,'Энэ талбарыг бөглөнө үү.');if(String(d.desc||'').length>80)add('desc','Гарчиг 80 тэмдэгтээс урт байна.');if(String(d.description||'').length>2000)add('description','Тайлбар 2000 тэмдэгтээс урт байна.');if(d.contactRole==='agent'&&!present(d.agencyName))add('agencyName','Агентлагийн нэр оруулна уу.');if(d.contactPhone&&!/^\+?[\d\s()-]{8,25}$/.test(d.contactPhone))add('contactPhone','Утасны дугаараа шалгана уу.');for(const name of ['videoUrl','tourUrl'])if(!validListingLink(d[name]))add(name,'https холбоос оруулна уу.');if(!listingPhotoDraft.length&&!d.photos?.length)add('photos','Байрны бодит зургаас хамгийн багадаа нэгийг нэмнэ үү.');if(editorPhotoBusy)add('photos','Зураг боловсруулж дуустал хүлээнэ үү.')}
 for(const key of step===0?['floor','totalFloors','bathrooms','year']:step===1?['parkingSpaces','minimumTerm']:[])if(present(d[key])&&!Number.isInteger(Number(d[key])))add(key,'Бүхэл тоо оруулна уу.');return errors;
}
function showListingErrors(errors){const host=document.querySelector('#listing-editor-form .editor-errors');if(host){host.hidden=false;host.innerHTML='<b>Мэдээллээ шалгана уу</b><ul>'+errors.map(e=>{const label=document.querySelector('label[for="listing-'+e.field+'"]')?.textContent?.replace(/\*/g,'').trim()||({location:'Газрын зураг',photos:'Байрны зураг',ack:'Мэдээллийн баталгаа'}[e.field])||e.field;return `<li><a href="#listing-${e.field}" onclick="event.preventDefault();document.getElementById('listing-${e.field}')?.focus()">${esc(label)}: ${esc(e.message)}</a></li>`}).join('')+'</ul>'};const input=document.getElementById('listing-'+errors[0]?.field);input?.focus();host?.scrollIntoView?.({behavior:'smooth',block:'center'})}
function listingNumber(value){return value!==''&&value!==null&&value!==undefined&&Number.isFinite(Number(value))?Number(value):null}
function buildListingRecord(d,id=Date.now()){
 const nullable=key=>listingNumber(d[key]);const fee=['included','none'].includes(d.feeMode)?0:nullable('feeMnt');
 return {...d,id,schemaVersion:2,local:true,currency:'MNT',type:Number(d.type),size:nullable('size'),totalSize:nullable('totalSize'),floor:nullable('floor'),totalFloors:nullable('totalFloors'),bathrooms:nullable('bathrooms'),year:nullable('year'),rooms:d.rooms==='shared'?'shared':nullable('rooms'),price:d.priceNegotiable?null:nullable('price'),deposit:d.deal==='sale'?0:Number(d.deposit||0),feeMnt:fee,parking:d.parkingStatus==='available'||!!d.garage,parkingFee:Number(d.parkingFee||0),parkingSpaces:nullable('parkingSpaces'),pet:d.petPolicy==='yes',furnished:d.furnishing==='full',balcony:d.other?.includes('balcony')||false,latitude:nullable('latitude'),longitude:nullable('longitude'),photos:listingPhotoDraft.slice(),createdAt:d.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),editorStep:undefined};
}
function submitListingEditor(event){event.preventDefault();const d=listingStep<3?captureListingDraft(event.target):prepareListingDraft();clearTimeout(editorSaveTimer);
 if(listingStep<3){const errors=validateListingDraft(d,listingStep);if(errors.length){showListingErrors(errors);return}listingStep++;d.editorStep=listingStep;if(!persistListingDraft()){listingStep--;return}render();scrollTo(0,0);return}
 for(let step=0;step<3;step++){const errors=validateListingDraft(d,step);if(errors.length){listingStep=step;render();showListingErrors(errors);return}}
 if(!new FormData(event.target).has('ack')){showListingErrors([{step:3,field:'ack',message:'Мэдээллээ шалгаж, зөвшөөрлөө тэмдэглэнэ үү.'}]);return}
 const returnTo=d.returnTo||'my/listings',id=d.editId||Date.now(),h=adminPrepareListing(buildListingRecord(d,id));delete h.editId;delete h.returnTo;const previous=flowState.listings.slice(),oldDraft=flowState.draft;
 const at=flowState.listings.findIndex(item=>item.id===id);if(at>=0)flowState.listings[at]=h;else flowState.listings.push(h);flowState.draft={};
 if(!persistFlows()){flowState.listings=previous;flowState.draft=oldDraft;return}
 const homeIndex=homes.findIndex(item=>item.id===id);if(homeIndex>=0)homes[homeIndex]=h;else homes.push(h);
 listingPhotoDraft=[];listingStep=0;editorReady=false;afterListingLocationSaved(h,returnTo);toast(adminReview(h)==='pending'?'Зар хяналтад илгээгдлээ · Админ батлахыг хүлээнэ':at>=0?'Зарын мэдээлэл шинэчлэгдлээ':'Демо зар энэ браузерт хадгалагдлаа');
}
function editLocalListing(id,returnTo='my/listings'){const h=flowState.listings.find(item=>item.id===id);if(!h)return;const d={...listingDraftDefaults(),...h,editId:id,editorStep:0,returnTo};
 if(h.schemaVersion!==2){d.totalSize=h.totalSize??'';d.totalFloors=h.totalFloors??'';d.bathrooms=h.bathrooms??'';d.year=h.year??'';d.parkingStatus=h.parking?'available':'none';d.petPolicy=h.pet?'yes':'no';d.furnishing=h.furnished?'full':'none';d.priceNegotiable=h.price===null;d.feeMode=h.feeMnt===0?'none':'separate'}
 flowState.draft=JSON.parse(JSON.stringify(d));listingPhotoDraft=(h.photos||[]).slice();listingStep=0;editorReady=true;persistFlows();goFlow(returnTo.startsWith('pro/')?'pro/new':'listing/new');scrollTo(0,0);
}
function moveListingPhoto(from,to){if(from===to||to<0||to>=listingPhotoDraft.length)return;const photo=listingPhotoDraft.splice(from,1)[0];listingPhotoDraft.splice(to,0,photo);syncListingPhotos()}
function removeListingPhoto(index){listingPhotoDraft.splice(index,1);syncListingPhotos()}
function syncListingPhotos(){flowState.draft.photos=listingPhotoDraft.slice();const host=document.getElementById('listing-photo-preview');if(host)host.innerHTML=editorPhotosMarkup();persistListingDraft()}
async function readEditorPhotos(input){const files=Array.from(input.files||[]);if(!files.length)return;if(files.length+listingPhotoDraft.length>PHOTO_LIMIT||files.some(file=>file.size>8*1024*1024||!['image/jpeg','image/png'].includes(file.type))){toast('10 хүртэл JPEG / PNG зураг. Нэг зураг 8 MB хүртэл.');input.value='';return}
 editorPhotoBusy=true;const status=document.getElementById('listing-photo-status');if(status)status.textContent='Зураг боловсруулж байна…';
 try{const photos=[];for(const file of files){const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const photo=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{try{const scale=Math.min(1,1400/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let out=canvas.toDataURL('image/jpeg',.78);if(out.length>400000)out=canvas.toDataURL('image/jpeg',.55);resolve(out)}catch(error){reject(error)}};img.onerror=reject;img.src=src});photos.push(photo)}listingPhotoDraft.push(...photos);syncListingPhotos();if(status)status.textContent=listingPhotoDraft.length+' зураг нэмэгдлээ.'}catch{if(status)status.textContent='Зураг уншиж чадсангүй. Өөр JPEG / PNG зураг сонгоно уу.'}finally{editorPhotoBusy=false;input.value=''}
}
function listingFeeText(h){if(h.feeMode==='included')return 'Үндсэн үнэд багтсан';if(h.feeMode==='none')return 'Төлбөргүй';if(h.feeMode==='actual')return 'Бодит хэрэглээгээр'+(h.feeMnt!==null&&h.feeMnt!==undefined?' · ~'+formatMnt(h.feeMnt):'');return h.feeMnt!==null&&h.feeMnt!==undefined?formatMnt(h.feeMnt):'Оруулаагүй'}
function listingFloorText(h){if(h.floor===null||h.floor===undefined||h.floor==='')return 'Давхар оруулаагүй';return h.floor+(h.totalFloors?' / '+h.totalFloors:'')+' давхар'}
function listingAddress(h){return [h.province||'Улаанбаатар',h.area,h.khoroo,h.address,h.buildingNo,h.showUnit&&h.unit?h.unit+' тоот':''].filter(Boolean).join(' · ')}
function listingMoveIn(h){return h.moveIn==='immediate'?'Шууд нүүх боломжтой':h.moveIn==='negotiable'?'Тохиролцоно':h.moveIn==='date'?h.moveInDate:'Оруулаагүй'}
function listingPetText(h){return {yes:'Зөвшөөрнө',no:'Зөвшөөрөхгүй',negotiable:'Тохиролцоно'}[h.petPolicy]||(h.pet?'Зөвшөөрнө':'Оруулаагүй')}
function listingFurnishingText(h){return {full:'Бүрэн тавилгатай',partial:'Хагас тавилгатай',none:'Тавилгагүй'}[h.furnishing]||(h.furnished?'Бүрэн тавилгатай':'Оруулаагүй')}
function listingParkingText(h){return h.garage?'Гаражтай'+(h.parkingFee?' · '+formatMnt(h.parkingFee)+' / сар':''):h.parkingStatus==='negotiable'?'Тохиролцоно':h.parking||h.parkingStatus==='available'?'Байгаа'+(h.parkingFee?' · '+formatMnt(h.parkingFee)+' / сар':' · Үнэгүй'):'Байхгүй'}
function listingRows(rows){return `<div class="rows">${rows.map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value===null||value===undefined||value===''?'Оруулаагүй':value)}</b></div>`).join('')}</div>`}
function listingPriceRows(h){return listingRows([...(h.deal==='sale'?[]:[['Барьцаа',formatMnt(h.deposit)]]),[h.deal==='sale'?'Худалдах үнэ':listingRentLabel(h),formatMnt(h.price)],['СӨХ / сар',listingFeeText(h)],['Үүнд багтсан',(h.feeIncluded||[]).map(v=>optionText('feeIncluded',v)).join(', ')||'Оруулаагүй'],['Нэмэлт зардал',h.feeNote],['Зогсоол',listingParkingText(h)],...(h.minimumTerm?[['Хамгийн бага хугацаа',h.minimumTerm+' '+optionText('period',h.rentPeriod||'month')]]:[])])}
function listingInfoRows(h){return listingRows([['Байрны төрөл',types[h.type]],['Хотхон / Нэр',h.name],['Хаяг',listingAddress(h)],['Ашигтай / нийт талбай',h.size+' м² / '+(h.totalSize?h.totalSize+' м²':'Оруулаагүй')],['Давхар',listingFloorText(h)],['Өрөө / ариун цэврийн өрөө',(h.rooms==='shared'?'Хажуу өрөө':h.rooms??'Оруулаагүй')+' / '+(h.bathrooms??'Оруулаагүй')],['Цонхны чиглэл',optionText('directions',h.direction)],['Барилгын хийц',optionText('structure',h.structure)],['Нүүх боломжтой өдөр',listingMoveIn(h)],['Ашиглалтад орсон он',h.year],['Цахилгаан шат',h.elevator?'Байгаа':'Байхгүй'],['Тавилга',listingFurnishingText(h)],['Тэжээвэр амьтан',listingPetText(h)],['Дуплекс',h.duplex?'Тийм':'Үгүй'],['Тамхи',{no:'Хориглоно',yes:'Зөвшөөрнө',negotiable:'Тохиролцоно'}[h.smoking]]])}
function listingOptionLabels(h,group){return (h[group]||[]).filter(key=>LISTING_OPTIONS[group]?.some(([k])=>k===key)).map(key=>optionText(group,key))}
function listingOptionChips(labels,empty='Мэдээлэл оруулаагүй'){return labels.length?`<div class="listing-option-chips">${labels.map(label=>`<span>${icon('check')}${esc(label)}</span>`).join('')}</div>`:`<p class="muted">${empty}</p>`}
function listingEquipment(h){return `<h3 class="listing-subheading">Халаалт</h3><p>${optionText('heating',h.heating)}</p><h3 class="listing-subheading">Хөргөлт</h3>${listingOptionChips(listingOptionLabels(h,'cooling'))}<h3 class="listing-subheading">Тавилга, ахуйн хэрэгсэл</h3>${listingOptionChips(listingOptionLabels(h,'amenities'))}<h3 class="listing-subheading">Бусад байгууламж</h3>${listingOptionChips(listingOptionLabels(h,'other'))}`}
function listingContactRows(h){return listingRows([['Зар оруулагч',{owner:'Өмчлөгч',agent:'Зуучлагч',representative:'Итгэмжлэгдсэн төлөөлөгч'}[h.contactRole]],['Нэр',h.contactName],...(h.contactRole==='agent'?[['Агентлаг',h.agencyName]]:[]),['Утас',h.contactPhone],['Холбогдох цаг',h.contactHours]])}
function editorReview(d){const h=buildListingRecord(d,d.editId||0);return `<div class="editor-review-notice">${icon('eye')}<div><b>Зар дээр харагдах мэдээллээ шалгана уу</b><p>Өөрчлөх бол холбогдох алхам руу буцаж засна. Оруулаагүй мэдээллийг автоматаар нөхөхгүй.</p></div></div><article class="editor-review-card"><div class="editor-review-photo"><img src="${listingPhotoDraft[0]||'assets/listing-placeholder.svg'}" alt="Зарын нүүр зураг"><span>${listingPhotoDraft.length} зураг</span></div><div><span class="badge">${types[h.type]}</span><h2>${esc(h.name)}</h2><h3>${propertyPriceMarkup(h)}</h3><p>${esc(h.desc)}</p><p class="muted">${esc(listingAddress(h))}</p></div></article>${editorSection('Үнийн мэдээлэл',listingPriceRows(h))}${editorSection('Газрын зураг дээрх байршил',listingReviewMap(h))}${editorSection('Дэлгэрэнгүй мэдээлэл',listingInfoRows(h))}${editorSection('Тоноглол ба аюулгүй байдал',listingEquipment(h)+listingOptionChips(listingOptionLabels(h,'security')))}${editorSection('Тайлбар ба ойр орчин',`<p class="listing-user-text">${esc(h.description)}</p>${listingRows([['Нийтийн тээвэр',h.nearbyTransit],['Сургууль / Цэцэрлэг',h.nearbySchool],['Үйлчилгээ',h.nearbyServices],['Видео',h.videoUrl],['3D аялал',h.tourUrl]])}`)}${editorSection('Зар оруулагч',listingContactRows(h))}${adminListingPolicyNote(d)}<label class="editor-final-consent"><input id="listing-ack" type="checkbox" name="ack" required> Мэдээллээ шалгасан. Энэ нь зөвхөн браузерт хадгалагдах демо зар гэдгийг ойлгосон.</label>`}
function renderListingEditor(){const d=prepareListingDraft(),step=listingStep;return `<div class="wrap listing-editor"><div class="editor-heading"><div><div class="eyebrow">ӨӨРИЙН ОРОН ЗАЙГАА ХУВААЛЦААРАЙ</div><h1>${d.editId?'Зар засах':'Зар нэмэх'}</h1><p>Байрны мэдээллээ бүрэн оруулаарай. Таны сонгосон нөхцөл, зураг, тайлбар зарын дэлгэрэнгүйд харагдана.</p></div><a href="#/${d.returnTo||'my/listings'}">${icon('folder')} Миний зарууд</a></div><ol class="editor-steps">${EDITOR_STEPS.map((name,i)=>`<li class="${i===step?'current':i<step?'complete':''}"><button type="button" ${i>step?'disabled':''} ${i===step?'aria-current="step"':''} onclick="changeListingStep(${i})"><span>${i<step?icon('check'):i+1}</span><b>${name}</b></button></li>`).join('')}</ol><div class="editor-layout"><form id="listing-editor-form" data-editor-step="${step}" novalidate oninput="listingEditorInput(event)" onchange="listingEditorChange(event)" onsubmit="advanceListing(event)"><div class="editor-step-heading"><span>АЛХАМ ${step+1} / 4</span><h2>${EDITOR_STEPS[step]}</h2><p><em>*</em> тэмдэгтэй талбаруудыг заавал бөглөнө.</p></div>${step===0?editorBasic(d):step===1?editorPricing(d):step===2?editorFacilities(d):editorReview(d)}<div class="editor-errors" role="alert" hidden></div><div class="editor-form-actions"><button type="button" onclick="${step?'changeListingStep('+(step-1)+')':"goFlow('"+(d.returnTo||'my/listings')+"')"}">${icon('arrow-left')}${step?'Буцах':'Миний зарууд'}</button><button class="primary" type="submit">${step===3?'Демо зарыг хадгалах':'Дараах алхам'}${icon(step===3?'check':'arrow-right')}</button></div></form><aside class="editor-side"><div class="editor-side-icon">${icon('file-text')}</div><h3>Бүрэн мэдээлэлтэй зар</h3><p>Дэлгэрэнгүй мэдээлэл нь хэрэглэгчид байраа зөв сонгоход тусална.</p><ul><li>Үнэ, барьцаа, нэмэлт төлбөр</li><li>Бодит талбай, өрөө ба давхар</li><li>Тоноглол, аюулгүй байдал</li><li>Бодит зураг ба тодорхой тайлбар</li></ul><button type="button" onclick="saveListingDraftButton()">${icon('bookmark')}Түр хадгалах</button><p id="editor-save-status" role="status">Энэ браузерт түр хадгална</p><div class="editor-local-note">Демо горим · Зар нийтэд илгээгдэхгүй.</div></aside></div></div>`}
function listingRentLabel(h){return h.rentPeriod==='day'?'Өдрийн түрээс':h.rentPeriod==='week'?'Долоо хоногийн түрээс':'Сарын түрээс'}
function listingPeriodSuffix(h){return h.rentPeriod==='day'?'/ өдөр':h.rentPeriod==='week'?'/ долоо хоног':'/ сар'}
function listingDetailTags(h){return [h.furnishing&&listingFurnishingText(h),h.elevator&&'Цахилгаан шаттай',h.garage&&'Гаражтай',...listingOptionLabels(h,'other')].filter(Boolean).slice(0,5)}
function listingDetailNav(){const sections=[['price','Үнийн мэдээлэл'],['details','Дэлгэрэнгүй мэдээлэл'],['options','Тоноглол'],['security','Хамгаалалт / аюулгүй байдал'],['transactions','Хэлцлийн мэдээлэл'],['tour','3D аялал / Видео'],['location','Байршил ба ойр орчин'],['car','Автомашин'],['transport','Нийтийн тээвэр'],['description','Дэлгэрэнгүй тайлбар'],['agent','Зар оруулагч'],['other','Бусад зар']];return `<div class="detail-section-nav" role="navigation" aria-label="Зарын мэдээллийн хэсгүүд"><div class="detail-tabbar">${[['price','Үнэ'],['details','Дэлгэрэнгүй'],['options','Тоноглол'],['security','Аюулгүй байдал']].map(([key,label],i)=>`<button class="detail-tab ${i===0?'active':''}" data-section-link="${key}" onclick="jumpToDetailSection('${key}')">${label}</button>`).join('')}<button class="detail-nav-toggle" aria-label="Бүх хэсгийг дэлгэх" aria-expanded="false" aria-controls="detail-section-menu" onclick="toggleDetailSections(this)">${icon('chevron-down')}</button></div><div id="detail-section-menu" class="detail-section-menu" hidden>${sections.map(([key,label],i)=>`<button data-section-link="${key}" class="${i===0?'active':''}" onclick="jumpToDetailSection('${key}')">${label}</button>`).join('')}</div></div>`}
function listingSectionHeading(id,title){return `<h2 id="detail-${id}" data-detail-section="${id}">${title}</h2>`}
function listingLocationPoint(h){return Number.isFinite(h.latitude)&&Number.isFinite(h.longitude)?[h.latitude,h.longitude]:(h.province==='Улаанбаатар'||!h.province?districtLocations[h.area]:null)}
function focusListingLocation(id){const h=homes.find(item=>item.id===id),point=h&&listingLocationPoint(h);if(!point)return;const zoom=Number.isFinite(h.latitude)&&Number.isFinite(h.longitude)?15:11;if(isMobileView()){mapView={center:{lng:point[1],lat:point[0]},zoom};mobileMapMode='map';activeDetail=null;query=String(id);category=h.type;filter=defaultFilter();goFlow('map/'+h.type);return}propertyMap?.jumpTo({center:[point[1],point[0]],zoom})}
function openListingMapsMe(id){const h=homes.find(item=>item.id===id),point=h&&listingLocationPoint(h);if(!point)return;const url=mapsMeUrl(point[0],point[1],h.name);modal(`<h2>MAPS.ME дээр нээх</h2><p>${esc(listingAddress(h))}</p><p class="muted">${h.latitude!==null&&h.latitude!==undefined?'Зар оруулагчийн оруулсан координат':'Дүүргийн ерөнхий төв цэг'}</p><a class="mapsme-open-link" href="${esc(url)}">MAPS.ME апп нээх ${icon('external-link')}</a>`)}
function listingDetailMarkup(h){const id=h.id,photoCount=h.photos?.length||(h.local?0:4),shown=h.local?Math.min(photoCount,3):3,head=listingSectionHeading;
 const enquiries=flowState.requests.filter(item=>item.propertyId===id).length;
 const other=officeRelatedHomes(h).slice(0,2);
 return `<section class="details" aria-label="Зарын дэлгэрэнгүй"><div class="detail-top"><b>Зар № ${id}</b><div class="detail-head-actions"><button aria-label="Хуваалцах" title="Хуваалцах" onclick="share(${id})">${icon('share')}</button><button data-heart="${id}" aria-pressed="${saved.includes(id)}" aria-label="Хадгалах" onclick="save(${id},event)">${heartIcon(saved.includes(id))}</button><button aria-label="Хаах" onclick="closeDetail()">${icon('close')}</button></div></div>
 <div class="detail-gallery ${shown<2?'single-photo':''}">${Array.from({length:Math.max(1,shown)},(_,i)=>`<button onclick="gallery(${id},${i})" aria-label="Зураг ${i+1} үзэх"><img src="${imageFor(h,i)}" alt="Байрны зураг ${i+1}"></button>`).join('')}<span class="detail-photo-count">${icon('image')}${photoCount} зураг</span></div>
 <div class="detail-id"><span>Зарын дугаар ${id}</span><span>${h.updatedAt?'Шинэчилсэн ':''}${h.updatedAt||h.createdAt?esc((h.updatedAt||h.createdAt).slice(0,10)):'Жишээ зар'}</span></div><div class="detail-body"><p class="notice">${h.local?'Таны оруулсан мэдээлэл · Браузерт хадгалсан демо':'Жишээ зар · Үнэ төгрөгөөр (₮) · Бодит санал биш'}</p><span class="badge">${h.local?'ТАНЫ ДЕМО ЗАР':'ЖИШЭЭ МЭДЭЭЛЭЛ'}</span><h1>${propertyPriceMarkup(h)}</h1><p>${esc(h.desc)}</p>
 <div class="facts"><div>${categoryIcon(h.type)}<p>${types[h.type]}</p></div><div>${icon('area')}<p>${h.size} м²</p></div><div>${icon('stairs')}<p>${listingFloorText(h)}</p></div><div>${icon('wallet')}<p>СӨХ ${listingFeeText(h)}</p></div></div><button class="transaction-link" onclick="goFlow('complex/${buildingNames().indexOf(h.name)}')">${icon('pin')}<span class="transaction-label">${esc(h.area)} · Хотхоны мэдээлэл</span>${icon('chevron-right')}</button><div class="detail-tags">${listingDetailTags(h).map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="detail-stats">Энэ браузерт · ${saved.includes(id)?'Хадгалсан':'Хадгалаагүй'} · ${enquiries} лавлагаа</p>${listingDetailNav()}
 ${head('price','Үнийн мэдээлэл')}${listingPriceRows(h)}${head('details','Дэлгэрэнгүй мэдээлэл')}${listingInfoRows(h)}${head('options','Тоноглол')}${listingEquipment(h)}${head('security','Хамгаалалт / аюулгүй байдал')}${listingOptionChips(listingOptionLabels(h,'security'),'Аюулгүй байдлын байгууламжийн мэдээлэл оруулаагүй.')}
 ${head('transactions','Хэлцлийн мэдээлэл')}<p class="notice">Бодит хэлцлийн мэдээллийн сан холбогдоогүй. Зар оруулагчийн санал болгосон үнэ дээрх хэсэгт байна.</p>
 ${head('tour','3D аялал / Видео')}${h.tourUrl&&validListingLink(h.tourUrl)?`<a class="detail-external-link" href="${esc(h.tourUrl)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}3D аялал нээх</a>`:''}${h.videoUrl&&validListingLink(h.videoUrl)?`<a class="detail-external-link" href="${esc(h.videoUrl)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}Видео үзэх</a>`:''}${!h.tourUrl&&!h.videoUrl?'<p class="muted">Видео / 3D аяллын холбоос оруулаагүй.</p>':''}
 ${head('location','Байршил ба ойр орчин')}<div class="listing-location-card">${icon('pin')}<p>${esc(listingAddress(h))}</p>${listingLocationPoint(h)?`<button onclick="focusListingLocation(${id})">Газрын зураг дээр харах</button><span>${h.latitude!==null&&h.latitude!==undefined?'Зар оруулагчийн координат':'Дүүргийн ерөнхий төв цэг'}</span>`:'<span>Координат оруулаагүй.</span>'}</div>${listingRows([['Сургууль / Цэцэрлэг',h.nearbySchool],['Ойр орчны үйлчилгээ',h.nearbyServices]])}
 ${head('car','Автомашин ба зогсоол')}${listingRows([['Зогсоол',listingParkingText(h)],['Зогсоолын тоо',h.parkingSpaces],['Гараж',h.garage?'Байгаа':'Байхгүй']])}
 ${head('transport','Нийтийн тээвэр')}<p class="listing-user-text">${esc(h.nearbyTransit||'Нийтийн тээврийн мэдээлэл оруулаагүй.')}</p>
 ${head('description','Дэлгэрэнгүй тайлбар')}<p class="listing-user-text">${esc(h.description||h.desc||'Тайлбар оруулаагүй.')}</p>
 ${head('agent',officeIdentity(h)?'Зуучлалын байгууллага':'Зар оруулагчийн мэдээлэл')}${officeListingCard(h)}
 ${head('other',officeIdentity(h)?'Байгууллагын бусад зар':'Зар оруулагчийн бусад зар')}<div class="cards detail-other-homes">${other.map(card).join('')}</div>${!other.length?'<p class="muted">Бусад зар байхгүй.</p>':''}${officeRelatedLink(h)}<button class="detail-report-button" onclick="report(${id})">Зар мэдээлэх</button></div>
 <div class="detail-actions"><span class="contact-tip">Демо · Бодит мессеж илгээгдэхгүй</span><button onclick="contact(${id},'phone')" aria-label="Утсаар лавлах" title="Утсаар лавлах">${icon('phone')}</button><button onclick="contact(${id})" aria-label="Чатаар лавлах" title="Чатаар лавлах">${icon('message')}</button><button class="primary" onclick="contact(${id})">${icon('send')}<span>Мессежээр лавлах</span></button></div></section>`;
}
